import re

def tr_lower(s: str) -> str:
    """Türkçe kurallarına göre küçük harfe çevirir."""
    # Önce büyük İ ve I karakterlerini özel olarak değiştiriyoruz
    # Sonra standart lower() metodunu çağırıyoruz. 
    # Ancak doğrudan replace kullanmak daha güvenlidir çünkü bazı Unicode varyasyonları sorun çıkarabilir.
    res = []
    for char in s:
        if char == 'İ':
            res.append('i')
        elif char == 'I':
            res.append('ı')
        else:
            res.append(char.lower())
    return "".join(res)

def tr_upper(s: str) -> str:
    """Türkçe kurallarına göre büyük harfe çevirir."""
    res = []
    for char in s:
        if char == 'i':
            res.append('İ')
        elif char == 'ı':
            res.append('I')
        else:
            res.append(char.upper())
    return "".join(res)

def tr_sorted(words: list[str]) -> list[str]:
    """Kelimeleri Türk alfabesine göre sıralar."""
    # Belirtilen özel karakter sırası
    alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    # Karakterlerin indekslerini bir sözlükte tutalım (Hızlı erişim için)
    char_order = {char: i for i, char in enumerate(alphabet)}

    def get_sort_key(word: str):
        # Kelimeyi küçük harfe çevirerek karşılaştırma yapıyoruz
        lower_word = tr_lower(word)
        key = []
        for char in lower_word:
            if char in char_order:
                # Alfabetik karakter ise sırasını ver (alfabeye göre 0, 1, ...)
                # Alfabenin dışındakiler için Unicode değerini kullanacağız.
                # Ancak "listedeki tüm karakterlerden önce gelir" dendiği için 
                # alfabedekilere yüksek bir offset ekleyip diğerlarını düşük tutmalıyız.
                key.append(char_order[char] + 1000) # Alfabeyi sona atıyoruz (veya tam tersi?)
                # "Bu listede olmayan karakterler... listedeki tüm karakterlerden önce gelir"
                # O halde alfabedekilere yüksek bir değer verelim, diğerlarına düşük.
            else:
                key.append(ord(char)) 

        # Aslında mantık şu olmalı: 
        # Karakter alfabetikse -> özel sırası (0-28 arası)
        # Karakter değilse -> Unicode değeri ama alfabeden küçük olacak şekilde.

        # Yeniden kurgulayalım:
        key = []
        for char in lower_word:
            if char in char_order:
                # Alfabedeki karakterler için (0, 1, 2...)
                # Diğerlerinden önce gelmesi için Unicode değerinden çok daha küçük bir sayı verilmeli.
                # Ama "diğerleri listedeki tüm karakterlerden önce gelir" diyor.
                # Yani: [Noktalama/Diğer] < [a-z (Türkçe)]
                key.append(char_order[char] + 1000) # Alfabeyi sona atıyoruz
            else:
                # Diğer karakterler en başta olacak. Unicode değerine göre sıralanacaklar.
                # Alfabetik karakterlerin başladığı yer olan 1000'den küçük bir değer verelim.
                key.append(ord(char))

        # Ancak "diğerleri kendi aralarında Unicode kod noktasına göre" denmiş.
        # Eğer iki karakter de listede değilse, ord() kullanmak doğru.
        # Ama eğer biri listede diğeri değilse, liste dışı olan önce gelmeli.

        # Doğru mantık: 
        # Her karakter için bir tuple döndürelim: (listede_mi?, değer)
        # listede_mi? -> False (0) ise daha küçük olur, True (1) ise daha büyük.
        # Ama "diğerleri listedeki tüm karakterlerden önce gelir" dediği için:
        # Karakter listede değilse -> (0, ord(char))
        # Karakter listedeyse -> (1, char_order[char])

        key = []
        for char in lower_word:
            if char in char_order:
                key.append((1, char_order[char]))
            else:
                key.append((0, ord(char)))
        return key

    # Python'un sort() metodu "stable" (kararlı) olduğu için 
    # eşit kelimelerde orijinal sırayı korur.
    return sorted(words, key=get_sort_key)

